    #[tokio::test]
    async fn process_sse_chunk_content_only_sends_no_thinking_close() {
        // A content delta with no open thinking phase sends only Content
        // (the old code sent a spurious Thinking(false) on every delta).
        let json = r#"{"choices":[{"delta":{"content":"hello"},"finish_reason":"stop"}]}"#;
        let chunk: SseChunk = serde_json::from_str(json).unwrap();

        let (tx, mut rx) = mpsc::channel(16);
        let mut state = ParseState::new();

        process_sse_chunk(chunk, &tx, &mut state).await;
        drop(tx);

        let mut chunks = Vec::new();
        while let Ok(msg) = rx.try_recv() {
            chunks.push(msg);
        }

        assert_eq!(chunks.len(), 1);
        assert!(matches!(chunks[0], super::ChatChunk::Content(..)));
        assert!(state.finish_reason_received);
        assert_eq!(state.chunks_received, 1);
        assert!(!state.reasoning_received);
    }

    #[tokio::test]
    async fn process_sse_chunk_interleaved_thinking_phases() {
        // Regression (M-3): reasoning→text→reasoning must emit a fresh
        // Thinking(true) for the second phase so the persisted blocks match
        // the display.
        let reasoning = r#"{"choices":[{"delta":{"reasoning_content":"hmm"}}]}"#;
        let text = r#"{"choices":[{"delta":{"content":"answer"}}]}"#;

        let (tx, mut rx) = mpsc::channel(16);
        let mut state = ParseState::new();

        process_sse_chunk(serde_json::from_str(reasoning).unwrap(), &tx, &mut state).await;
        process_sse_chunk(serde_json::from_str(text).unwrap(), &tx, &mut state).await;
        process_sse_chunk(serde_json::from_str(reasoning).unwrap(), &tx, &mut state).await;
        drop(tx);

        let mut chunks = Vec::new();
        while let Ok(msg) = rx.try_recv() {
            chunks.push(msg);
        }

        let expected: Vec<&str> = chunks
            .iter()
            .map(|c| match c {
                super::ChatChunk::Thinking(true) => "T+",
                super::ChatChunk::Thinking(false) => "T-",
                super::ChatChunk::Reasoning(_) => "R",
                super::ChatChunk::Content(_) => "C",
                _ => "?",
            })
            .collect();
        assert_eq!(expected, vec!["T+", "R", "T-", "C", "T+", "R"]);
    }

    #[tokio::test]
    async fn process_sse_chunk_reasoning_then_content_closes_phase() {
        let json = r#"{"choices":[{"delta":{"reasoning_content":"thinking...","content":"answer"}}]}"#;
        let chunk: SseChunk = serde_json::from_str(json).unwrap();

        let (tx, mut rx) = mpsc::channel(16);
        let mut state = ParseState::new();

        process_sse_chunk(chunk, &tx, &mut state).await;
        drop(tx);

        let mut chunks = Vec::new();
        while let Ok(msg) = rx.try_recv() {
            chunks.push(msg);
        }

        // Thinking(true), Reasoning, then the content delta closes the phase:
        // Thinking(false), Content.
        let expected: Vec<&str> = chunks
            .iter()
            .map(|c| match c {
                super::ChatChunk::Thinking(true) => "T+",
                super::ChatChunk::Thinking(false) => "T-",
                super::ChatChunk::Reasoning(_) => "R",
                super::ChatChunk::Content(_) => "C",
                _ => "?",
            })
            .collect();
        assert_eq!(expected, vec!["T+", "R", "T-", "C"]);
        assert!(state.reasoning_received);
        assert_eq!(state.chunks_received, 1);
    }

    // ---------------------------------------------------------------------------
    // append_utf8_safe — multibyte chars split across chunks (L-17)
    // ---------------------------------------------------------------------------

    #[test]
    fn append_utf8_safe_multibyte_split_across_chunks() {
        // "héllo" — the é (0xC3 0xA9) is split across two chunks.
        let mut pending: Vec<u8> = Vec::new();
        let mut buffer = String::new();

        append_utf8_safe(&mut pending, &mut buffer, b"h\xC3");
        assert_eq!(buffer, "h");
        assert_eq!(pending, vec![0xC3]);

        append_utf8_safe(&mut pending, &mut buffer, b"\xA9llo");
        assert_eq!(buffer, "héllo");
        assert!(pending.is_empty(), "no trailing bytes");
    }

    #[test]
    fn append_utf8_safe_ascii_and_complete_multibyte() {
        let mut pending: Vec<u8> = Vec::new();
        let mut buffer = String::new();

        append_utf8_safe(&mut pending, &mut buffer, "héllo".as_bytes());
        assert_eq!(buffer, "héllo");
        assert!(pending.is_empty(), "no trailing bytes");
    }

